export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type QuoteStep = {
  op: "quote";
  items: Item[];
};

export type Customer = {
  yearsWithMHPCO: number;
};

export type Scenario = {
  customer: Customer;
  steps: QuoteStep[];
};

export type ScenarioResult = {
  results: unknown[];
};

const PROCESSING_FEE = 5;

// Only the main item types. Components are priced separately: individually,
// or as a discounted block of 3 alike ones.
const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_BASE_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const isComponent = (item: Item): boolean =>
  COMPONENT_TYPES.includes(item.type);

// Modifiers are additive percentages of the UNMODIFIED base premium, never
// compounding multipliers, and are kept as exact fractions rather than float
// multipliers: 100 * 1.1 is 110.00000000000001 in IEEE-754. Only the final
// premium is rounded, so intermediate amounts stay fractional.
const percentOf = (amount: number, percent: number): number =>
  (amount * percent) / 100;

// Modifiers are signed terms in one additive sum, so a discount is simply a
// negative percentage. Naming the sign keeps it from riding on a single easily
// overlooked "-" at a call site.
const discountOf = (amount: number, percent: number): number =>
  -percentOf(amount, percent);

const FIRST_INSURANCE_PERCENT = 10;
const CURSE_PERCENT = 50;
const HIGH_ENCHANTMENT_PERCENT = 30;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const LOYALTY_DISCOUNT_PERCENT = 20;
const LOYALTY_THRESHOLD_YEARS = 2;
const FOLLOW_UP_DISCOUNT_PERCENT = 15;

const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];

// A group of exactly 3 alike components is offered at a block price. Any
// other count is priced per component.
const componentGroupPremium = (count: number): number =>
  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;

// Components are priced per group of alike ones, so each distinct type is
// counted and priced on its own.
const componentsPremium = (components: Item[]): number => {
  const distinctTypes = new Set(components.map((component) => component.type));

  return [...distinctTypes].reduce((sum, type) => {
    const alike = components.filter((component) => component.type === type);
    return sum + componentGroupPremium(alike.length);
  }, 0);
};

// Splits a quote's items into the two independently-priced kinds, so the
// main/component distinction is decided in exactly one place.
const partitionByComponent = (
  items: Item[],
): { mainItems: Item[]; components: Item[] } => ({
  mainItems: items.filter((item) => !isComponent(item)),
  components: items.filter(isComponent),
});

// Item-specific modifiers apply to the affected item's OWN base premium, not
// to the policy total. They are independent: a cursed, highly enchanted item
// carries both, so each item sums the surcharges that apply to it.
const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;

const surchargesFor = (item: Item): number => {
  const base = basePremiumOf(item);
  const curse = item.cursed ? percentOf(base, CURSE_PERCENT) : 0;
  const enchantment = isHighlyEnchanted(item)
    ? percentOf(base, HIGH_ENCHANTMENT_PERCENT)
    : 0;

  return curse + enchantment;
};

const itemSpecificModifiers = (mainItems: Item[]): number =>
  mainItems.reduce((sum, item) => sum + surchargesFor(item), 0);

// Policy-wide modifiers are percentages of the whole policy's base premium,
// taken from the UNMODIFIED base so item-specific modifiers never feed into
// them - that is what keeps modifiers additive instead of compounding.
// Discounts are negative terms.
const qualifiesForLoyalty = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;

const policyWideModifiers = (
  basePremium: number,
  customer: Customer,
  isFollowUp: boolean,
): number => {
  // First insurance applies to every quote, including follow-ups: the spec
  // treats each item in a quote as a first insurance regardless of customer
  // history, so this coexists with the follow-up discount.
  const firstInsurance = percentOf(basePremium, FIRST_INSURANCE_PERCENT);
  const loyalty = qualifiesForLoyalty(customer)
    ? discountOf(basePremium, LOYALTY_DISCOUNT_PERCENT)
    : 0;
  const followUp = isFollowUp
    ? discountOf(basePremium, FOLLOW_UP_DISCOUNT_PERCENT)
    : 0;

  return firstInsurance + loyalty + followUp;
};

// Amounts are rounded in MHPCO's favour, and the direction depends on who
// pays: a premium is owed TO MHPCO, so it rounds up. Only the final amount is
// rounded - every intermediate stays fractional.
const roundPremiumInMhpcoFavour = (premium: number): number =>
  Math.ceil(premium);

const quotePremium = (
  step: QuoteStep,
  customer: Customer,
  isFollowUp: boolean,
): number => {
  const { mainItems, components } = partitionByComponent(step.items);

  const basePremium =
    mainItems.reduce((sum, item) => sum + basePremiumOf(item), 0) +
    componentsPremium(components);

  const modifiers =
    itemSpecificModifiers(mainItems) +
    policyWideModifiers(basePremium, customer, isFollowUp);

  return roundPremiumInMhpcoFavour(basePremium + modifiers + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  // Every contract after the customer's first earns the follow-up discount, so
  // a quote's premium depends on its ordinal position among the customer's
  // quotes. Every step is currently a quote step, so the step index IS that
  // ordinal. When claim steps enter the type the two diverge, and this is the
  // one place that has to learn to count quote steps specifically.
  const results = scenario.steps.map((step, quoteIndex) => ({
    premium: quotePremium(step, scenario.customer, quoteIndex > 0),
  }));

  return { results };
};

import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Simplest case ---
  it("should charge only the processing fee for an empty item list — premium 5 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result).toEqual({ results: [{ premium: 5 }] });
  });

  // --- Base premiums per main item type ---
  it("should quote a plain sword — premium 115 G (100 base + 10 first insurance + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "sword", material: "steel", enchantment: 3, cursed: false },
          ],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("should quote a plain amulet — premium 71 G (60 base + 6 first insurance + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "amulet", material: "silver", enchantment: 2, cursed: false },
          ],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("should quote a plain staff — premium 93 G (80 base + 8 first insurance + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "staff", material: "oak", enchantment: 2, cursed: false },
          ],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 93 }] });
  });
  it("should quote a plain potion — premium 49 G (40 base + 4 first insurance + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "potion", material: "glass", enchantment: 1, cursed: false },
          ],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 49 }] });
  });

  // --- Component base premiums and the block of 3 alike ---
  it("should quote a single rune — base premium 25 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }] }],
    });

    // 25 base + 10% first insurance + 5 fee = 32.5, rounded up to 33 in
    // MHPCO's favour.
    expect(result).toEqual({ results: [{ premium: 33 }] });
  });
  it("should quote a single moonstone — base premium 25 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "moonstone" }] }],
    });

    // As with the rune test: 25 base + 10% + 5 fee = 32.5, rounded up to 33.
    expect(result).toEqual({ results: [{ premium: 33 }] });
  });
  it("should quote 2 runes — base premium 50 G (no block)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    });

    // 2 x 25 = 50 base, +10% first insurance, +5 fee = 60 exactly.
    expect(result).toEqual({ results: [{ premium: 60 }] });
  });
  it("should quote 3 runes — base premium 60 G (block applies)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }],
        },
      ],
    });

    // 3 alike components form a block: 60 base, NOT 3 x 25 = 75.
    // +10% first insurance, +5 fee = 71.
    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("should quote 4 runes — base premium 100 G (no block — block requires exactly 3)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
          ],
        },
      ],
    });

    // No block at 4: 4 x 25 = 100 base, +10% first insurance, +5 fee = 115.
    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("should quote 7 runes — base premium 175 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: Array.from({ length: 7 }, () => ({ type: "rune" })),
        },
      ],
    });

    // This test pins COMPONENT PRICING: no block at 7, so 7 x 25 = 175 base.
    // (The separate rounding test below shares this scenario but pins the
    // rounding rule instead.)
    // 175 base + 10% first insurance + 5 fee = 197.5, shown rounded as 198.
    expect(result).toEqual({ results: [{ premium: 198 }] });
  });
  it("should quote 2 runes + 1 moonstone — base premium 75 G (no block: different types)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "rune" },
            { type: "rune" },
            { type: "moonstone" },
          ],
        },
      ],
    });

    // "Alike" means exactly the same type, so 3 components form no block here:
    // runes (2 x 25 = 50) + moonstone (25) = 75 base, +10% + 5 fee = 87.5,
    // rounded up to 88.
    expect(result).toEqual({ results: [{ premium: 88 }] });
  });
  it("should quote 3 runes + 3 moonstones — base premium 120 G (two separate blocks)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            ...Array.from({ length: 3 }, () => ({ type: "rune" })),
            ...Array.from({ length: 3 }, () => ({ type: "moonstone" })),
          ],
        },
      ],
    });

    // Each type blocks separately: 60 (runes) + 60 (moonstones) = 120 base —
    // not one merged block, and not 6 x 25 = 150. +10% + 5 fee = 137.
    expect(result).toEqual({ results: [{ premium: 137 }] });
  });

  // --- Item-specific modifiers ---
  it("should add a 50% curse surcharge to the cursed item's base premium — cursed sword base 150 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "sword", material: "steel", enchantment: 3, cursed: true },
          ],
        },
      ],
    });

    // Modifiers are ADDITIVE percentages of the item's unmodified base, not
    // compounding: 100 base + 50 curse (50% of 100) + 10 first insurance
    // (10% of 100) = 160, + 5 fee = 165.
    //
    // Both integration examples pin this. The second one — cursed sword,
    // enchantment 7, 3-year customer — is decisive: "100 + 50 curse + 30 high
    // enchantment - 20 loyalty + 10 first insurance - 15 follow-up = 155 + 5
    // = 160". Loyalty there is 20 (20% of the unmodified 100), not 20% of the
    // modifier-inflated 180. If policy-wide modifiers applied to a base that
    // already included item modifiers, that example would not total 160.
    expect(result).toEqual({ results: [{ premium: 165 }] });
  });
  it("should add a 30% high-enchantment surcharge at enchantment 5 — sword base 130 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "sword", material: "steel", enchantment: 5, cursed: false },
          ],
        },
      ],
    });

    // Enchantment 5 is the INCLUSIVE threshold (spec: level >= 5 surcharges,
    // and "sword with exactly enchantment 5 → surcharge applies").
    // 100 base + 30 high enchantment (30% of 100) + 10 first insurance = 140,
    // + 5 fee = 145.
    expect(result).toEqual({ results: [{ premium: 145 }] });
  });
  it("should not add the high-enchantment surcharge at enchantment 4 — sword base 100 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "sword", material: "steel", enchantment: 4, cursed: false },
          ],
        },
      ],
    });

    // Exclusive side of the threshold: 4 is below 5, so no surcharge. With the
    // enchantment-5 test (145) this pins the boundary from both sides.
    // 100 base + 10 first insurance = 110, + 5 fee = 115.
    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("should apply both surcharges to a cursed sword with enchantment 5 — base 180 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "sword", material: "steel", enchantment: 5, cursed: true },
          ],
        },
      ],
    });

    // Both item-specific surcharges STACK additively — neither overrides the
    // other (spec: "if cursed, both surcharges apply").
    // 100 base + 50 curse + 30 high enchantment = 180 item base.
    // First insurance is 10% of the UNMODIFIED 100 base = 10, not 10% of 180.
    // 180 + 10 = 190, + 5 fee = 195.
    expect(result).toEqual({ results: [{ premium: 195 }] });
  });

  // --- Policy-wide modifiers ---
  it("should apply the 20% loyalty discount at exactly 2 years with MHPCO", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 2 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "sword", material: "steel", enchantment: 3, cursed: false },
          ],
        },
      ],
    });

    // 2 years is the INCLUSIVE threshold (spec: ">= 2 years", and "customer
    // with exactly 2 years → loyalty discount applies"). Loyalty is a negative
    // additive term on the unmodified base:
    // 100 base - 20 loyalty + 10 first insurance = 90, + 5 fee = 95.
    expect(result).toEqual({ results: [{ premium: 95 }] });
  });
  it("should not apply the loyalty discount at 1 year with MHPCO", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 1 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "sword", material: "steel", enchantment: 3, cursed: false },
          ],
        },
      ],
    });

    // Exclusive side of the loyalty threshold: 1 year is below 2, so no
    // discount. With the exactly-2-years test (95) this pins both sides.
    // 100 base + 10 first insurance = 110, + 5 fee = 115.
    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("should apply the 10% first insurance surcharge to every item in a quote", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "sword", material: "steel", enchantment: 3, cursed: false },
            { type: "amulet", material: "silver", enchantment: 2, cursed: false },
          ],
        },
      ],
    });

    // First insurance covers EVERY item: it is 10% of the summed policy base
    // (16 = 10% of 100 + 60), not 10 = 10% of the sword alone.
    // 160 base + 16 first insurance = 176, + 5 fee = 181.
    expect(result).toEqual({ results: [{ premium: 181 }] });
  });
  it("should apply the 15% follow-up discount on each contract after the first", () => {
    const sword = {
      type: "sword",
      material: "steel",
      enchantment: 3,
      cursed: false,
    };

    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [sword] },
        { op: "quote", items: [sword] },
      ],
    });

    // The discount keys off the quote's ORDINAL POSITION among quote steps,
    // not off customer.yearsWithMHPCO.
    //   1st quote: 100 base + 10 first insurance = 110, + 5 fee = 115.
    //   2nd quote: 100 base + 10 first insurance - 15 follow-up = 95,
    //              + 5 fee = 100.
    //
    // First insurance STILL applies to the follow-up contract — the two
    // modifiers coexist rather than being mutually exclusive. This is the
    // spec's binding answer to its own question: "each item in a quote is
    // treated as a first insurance, regardless of customer history", and its
    // second integration example sums both "+ 10 first insurance" and
    // "- 15 follow-up" in one calculation.
    expect(result).toEqual({ results: [{ premium: 115 }, { premium: 100 }] });
  });
  it("should add the 5 G processing fee at the very end of every premium", () => {
    const sword = {
      type: "sword",
      material: "steel",
      enchantment: 3,
      cursed: false,
    };
    const quoteFor = (yearsWithMHPCO: number) =>
      runScenario({
        customer: { yearsWithMHPCO },
        steps: [{ op: "quote", items: [sword] }],
      });

    const newcomer = quoteFor(0);
    const loyal = quoteFor(2);

    // Fee is added AFTER every percentage, never folded into the base.
    //   0 years: 100 + 10 first insurance = 110, + 5 fee = 115.
    //   2 years: 100 - 20 loyalty + 10 first insurance = 90, + 5 fee = 95.
    expect(newcomer).toEqual({ results: [{ premium: 115 }] });
    expect(loyal).toEqual({ results: [{ premium: 95 }] });

    // The ordering is what makes both results whole numbers. Were the fee
    // folded into the base first (105), the percentages would scale it:
    // 105 - 21 + 10.5 = 94.5, and the gap would be 21 rather than 20.
    const loyaltyGap =
      (newcomer.results[0] as { premium: number }).premium -
      (loyal.results[0] as { premium: number }).premium;
    expect(loyaltyGap).toBe(20);
  });

  // --- Modifier scope on multi-item policies ---
  it("should apply the curse surcharge only to the cursed item — cursed sword + plain amulet: 160 G base + 50 G curse = 210 G before further modifiers and fee", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "sword", material: "steel", enchantment: 3, cursed: true },
            { type: "amulet", material: "silver", enchantment: 2, cursed: false },
          ],
        },
      ],
    });

    // The spec's binding answer to "does the curse apply to the whole policy,
    // or just the cursed item?" — just the cursed item.
    //   policy base   = 100 sword + 60 amulet          = 160
    //   curse         = 50% of the SWORD's own 100     =  50  -> 210 subtotal
    //   first insur.  = 10% of the UNMODIFIED 160      =  16
    //   total         = 160 + 50 + 16 = 226, + 5 fee   = 231
    //
    // Two wrong answers this rules out:
    //   - curse as 50% of the 160 policy total -> 80, premium 261
    //   - first insurance on the curse-inflated 210 -> 21, premium 236
    expect(result).toEqual({ results: [{ premium: 231 }] });
  });

  // --- Rounding ---
  it("should round a premium of 197.5 G up to 198 G (in MHPCO's favor)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: Array.from({ length: 7 }, () => ({ type: "rune" })),
        },
      ],
    });

    // This test pins the ROUNDING RULE, not component pricing (the 7-rune
    // test above shares this scenario but pins the block behaviour).
    // The spec's worked example is exactly this number: "a premium
    // calculation that yields 197.5 G → final premium 198 G (rounded up)".
    // Premiums round UP because a higher premium favours MHPCO.
    expect(result).toEqual({ results: [{ premium: 198 }] });
  });
  it.todo("should round a payout of 350.5 G down to 350 G (in MHPCO's favor)");
  it.todo("should keep intermediate amounts as fractions and round only the final amount");

  // --- Integration examples ---
  it.todo("should quote a newcomer's cursed sword (0 years, steel, enchantment 3) — premium 165 G");
  it.todo("should quote a long-standing customer's second contract (3 years, cursed sword, enchantment 7) — premium 160 G");

  // --- Insurance sums and caps ---
  it.todo("should compute insurance sum 1600 G and cap 3200 G for a policy covering a sword and an amulet");
  it.todo("should compute insurance sum 2000 G and cap 4000 G for a policy covering two swords");
  it.todo("should compute insurance sum 1750 G for a sword and 3 runes — the block discount affects the premium only");
  it.todo("should base the cap on the unmodified insurance value — cursed sword (premium 165 G) still has cap 2000 G");

  // --- Standard reimbursement ---
  it.todo("should reimburse a regular sword (steel, enchantment 3) damaged 500 G — payout 400 G");
  it.todo("should reimburse a damaged rune (damage 200 G) — payout 100 G (no enchantment or material, no special clause)");

  // --- Special clauses ---
  it.todo("should reimburse damage to an item with enchantment >= 8 at 50% — dragon sword, enchantment 8, damage 1000 G → payout 400 G");
  it.todo("should fully reimburse dragon-material damage — dragon sword, enchantment 5, damage 800 G → payout 700 G");
  it.todo("should let the 50% rule win when both clauses apply — dragon sword, enchantment 9, damage 1000 G → payout 400 G");
  it.todo("should apply only the high-enchantment clause to a steel sword, enchantment 9, damage 1000 G → payout 400 G");

  // --- Deductible per damage event ---
  it.todo("should apply the 100 G deductible once per damaged item — sword 500 G + amulet 300 G → payout 600 G");
  it.todo("should treat two damage entries of the same type as separate damages with their own deductible");

  // --- Cap exhaustion ---
  it.todo("should report the remaining cap after a claim — sword (cap 2000 G), claim 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("should reduce a payout to the remaining cap — second claim of 1500 G → payout 600 G, remainingCap 0 G");

  // --- Error cases ---
  it.todo("should reject a quote containing an item with an unknown type (e.g. broomstick)");
  it.todo("should reject a claim whose damage references an item not part of the policy (amulet damaged, only a sword insured)");
  it.todo("should reject a claim whose damage references an item with an unknown type");
  it.todo("should reject a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured)");
  it.todo("should reject a claim containing a damage entry with a negative amount (-200)");

  // --- Scenario / CLI end-to-end ---
  it.todo("should return one result per step, in the order of the input steps");
  it.todo("should let a claim step reference the policy created by an earlier quote step via its zero-based index");
  it.todo("should process the schema example scenario (5 years, amulet quote then a 200 G fire claim)");
  it.todo("CLI should read a scenario from stdin and write {results: [...]} to stdout");
  it.todo("CLI should exit with a non-zero status and write an error to stderr for an invalid scenario, writing no results to stdout");
});

