// Amounts are rounded in the MHPCO's favor, and the direction depends on who
// pays: a premium is owed TO MHPCO, so it rounds up. (A payout is owed BY
// MHPCO, so it will round down - hence the rule, not the direction, is what
// this name states.) Applied once, where a step's result is emitted: every
// amount inside the pricing pipeline stays an exact fraction.
const roundPremiumInMhpcoFavor = (premium: number): number =>
  Math.ceil(premium);

// Returns the EXACT, unrounded premium. Rounding happens once, at the point
// the result is emitted - see runScenario.
const quotePremium = (
  step: QuoteStep,
  customer: Customer,
  isFollowUp: boolean,
): number => {
  const { mainItems, components } = partitionByComponent(step.items);

  const basePremium =
    mainItems.reduce((sum, item) => sum + basePremiumOf(item), 0) +
    componentsPremium(components);

  const modifiers =
    itemSpecificModifiers(mainItems) +
    policyWideModifiers(basePremium, customer, isFollowUp);

  return basePremium + modifiers + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  // Every contract after the customer's first earns the follow-up discount, so
  // a quote's premium depends on its ordinal position among the customer's
  // quotes. Every step is currently a quote step, so the step index IS that
  // ordinal. When claim steps enter the type the two diverge, and this is the
  // one place that has to learn to count quote steps specifically.
  const results = scenario.steps.map((step, quoteIndex) => ({
    premium: roundPremiumInMhpcoFavor(
      quotePremium(step, scenario.customer, quoteIndex > 0),
    ),
  }));

  return { results };
};
